INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (27, 16, "東山奈央", "A", "人助けが大好き！　前向き格闘娘", 2, "獣人族", "ヒヨリ", 0, 100101, "人助け、応援", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 155, 8, 44, "トゥインクルウィッシュ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 17, "種田梨沙", "O", "戦闘のサポートが得意な、心優しい少女", 2, "ヒューマン", "ユイ", 0, 100201, "料理、人間観察", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 158, 4, 47, "トゥインクルウィッシュ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 18, "早見沙織", "B", "クールで何事にも真っ直ぐな剣士", 2, "魔族", "レイ", 0, 100301, "読書、乗馬、お茶", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 163, 1, 46, "トゥインクルウィッシュ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 9, "諸星すみれ", "O", "探検好きのイタズラっ子", 5, "ヒューマン", "ミソギ", 0, 100401, "いたずら、探検", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 128, 8, 27, "リトルリリカル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (25, 12, "下田麻美", "O", "ヒーローに憧れる騎士見習いの少女", 8, "獣人族", "マツリ", 0, 100501, "ヒーローごっこ", "？？？", 146, 11, 40, "王宮騎士団（NIGHTMARE）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 13, "浅倉杏美", "O", "甘え上手なみんなの人気者", 7, "魔族", "アカリ", 0, 100601, "サックス", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 150, 11, 42, "悪魔偽王国軍（ディアボロス）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (23, 14, "雨宮天", "B", "プリン大好きゴースト娘", 7, "魔族", "ミヤコ", 0, 100701, "プリンを食べること", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 130, 1, 32, "悪魔偽王国軍（ディアボロス）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 14, "大空直美", "AB", "ボクは誰よりも美しい", 15, "エルフ", "ユキ", 0, 100801, "鏡で自分を見ること", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 150, 10, 40, "ヴァイスフリューゲル　ランドソル支部");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 17, "髙野麻美", "A", "前世を信じる中二病患者、「疾風の冥姫」", 13, "魔族", "アンナ", 0, 100901, "小説執筆", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 159, 7, 45, "トワイライトキャラバン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 16, "内田真礼", "O", "マホマホ王国のプリンセス", 10, "獣人族", "マホ", 0, 101001, "空想、ぬいぐるみ集め", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 155, 9, 42, "自警団（カォン）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (25, 15, "阿澄佳奈", "A", "人懐っこくてマシンガントークな妹系少女", 3, "ヒューマン", "リノ", 0, 101101, "お裁縫", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 156, 8, 44, "ラビリンス");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (24, 17, "大橋彩香", "A", "みんなのために超能力を使う眠り姫", 6, "エルフ", "ハツネ", 0, 101201, "妹と遊ぶこと、二度寝、昼寝、早寝", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 156, 12, 46, "フォレスティエ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (21, 18, "佳村はるか", "O", "オタク全開な魔法少女", 13, "魔族", "ナナカ", 0, 101301, "読書、魔法", "", 166, 8, 55, "トワイライトキャラバン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 15, "水瀬いのり", "AB", "頭脳明晰な美少女名探偵", 10, "獣人族", "カスミ", 0, 101401, "読書、推理", "test", 152, 11, 41, "自警団（カォン）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 21, "國府田マリ子", "O", "母性溢れる優しいみんなの「ミサト先生」", 6, "エルフ", "ミサト", 0, 101501, "絵本作り", "test", 165, 9, 54, "フォレスティエ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 17, "上坂すみれ", "O", "天真爛漫で人気者のカリスマモデル", 14, "魔族", "スズナ", 0, 101601, "ファッション", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 167, 4, 48, "ルーセント学院");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, 17, "高森奈津美", "A", "いつでも「なんくるないさ～」な天然娘", 10, "獣人族", "カオリ", 0, 101701, "踊り、空手", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 158, 7, 53, "自警団（カォン）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (14, 23, "伊藤静", "B", "多くの男性を魅了する無垢な女教師", 14, "魔族", "イオ", 0, 101801, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 162, 8, 52, "ルーセント学院");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 10, "日高里菜", "O", "お歌もにんじんも、ウサギさんも大好き♪", 5, "獣人族", "ミミ", 0, 102001, "かわいいもの集め", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 117, 4, 21, "リトルリリカル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, 12, "植田佳奈", "B", "泣き虫で臆病な守ってあげたい女の子", 9, "ヒューマン", "クルミ", 0, 102101, "観劇、おままごと", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 150, 6, 40, "サレンディア救護院");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 13, "原紗友里", "O", "人見知りであまのじゃくな女の子", 7, "魔族", "ヨリ", 0, 102201, "ゲーム全般", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 150, 11, 40, "悪魔偽王国軍（ディアボロス）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 14, "芹澤優", "B", "ぷうきちといつも一緒！", 9, "ヒューマン", "アヤネ", 0, 102301, "屋内でできる遊び", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 148, 5, 38, "サレンディア救護院");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 15, "悠木碧", "O", "お嬢さまのためにがんばるドジっ娘メイド", 9, "ヒューマン", "スズメ", 0, 102501, "ご奉仕", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 154, 12, 43, "サレンディア救護院");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, 17, "小岩井ことり", "B", "遊びと睡眠が何より大事なぐうたら娘", 11, "獣人族", "リン", 0, 102601, "あんパン", "test", 144, 1, 42, "牧場（エリザベスパーク）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (30, 16, "橋本ちなみ", "B", "運命の相手に一途すぎる乙女", 13, "魔族", "エリコ", 0, 102701, "実験、裁縫、料理", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 154, 7, 43, "トワイライトキャラバン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, 17, "堀江由衣", "A", "救護院を経営する優しい庶民派お嬢様", 9, "エルフ", "サレン", 0, 102801, "経営、お茶会", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 156, 10, 43, "サレンディア救護院");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (24, 17, "日笠陽子", "B", "歌って踊れる大人気アイドル", 4, "ヒューマン", "ノゾミ", 0, 102901, "舞台鑑賞、ダンス", "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", 157, 1, 40, "カルミナ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (31, 16, "佐藤聡美", "O", "トーゴクの神秘、オシエテクダサイ！", 15, "ヒューマン", "ニノン", 0, 103001, "忍法開発", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 163, 8, 51, "ヴァイスフリューゲル　ランドソル支部");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 18, "大坪由佳", "AB", "占いが得意な霊能少女", 7, "魔族", "シノブ", 0, 103101, "占い", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 157, 12, 42, "悪魔偽王国軍（ディアボロス）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 18, "松嵜麗", "AB", "一人前の商人を目指すパワフルお嬢様", 12, "ヒューマン", "アキノ", 0, 103201, "慈善事業", "この私とともにいる限り、\nお金に不自由はさせませんわ！", 157, 3, 45, "メルクリウス財団");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 20, "新田恵海", "B", "みんなを笑顔にするお笑い牧場主", 11, "ヒューマン", "マヒル", 0, 103301, "漫才", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 142, 3, 35, "牧場（エリザベスパーク）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (16, 22, "今井麻美", "A", "純情でほっとけない大人の女性", 12, "エルフ", "ユカリ", 0, 103401, "ウインドーショッピング", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 164, 3, 55, "メルクリウス財団");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (2, 8, "小倉唯", "A", "礼儀正しくしっかり者のちびっ子優等生", 5, "エルフ", "キョウカ", 0, 103601, "お勉強", "test", 118, 2, 21, "リトルリリカル");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 13, "茅原実里", "A", "義理堅くてからかい好きな剣術少女", 8, "ヒューマン", "トモ", 0, 103701, "剣術、年長者をからかう", "test", 149, 8, 43, "王宮騎士団（NIGHTMARE）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 14, "小清水亜美", "A", "読書が趣味の病弱少女", 11, "獣人族", "シオリ", 0, 103801, "読書、お散歩", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 153, 11, 40, "牧場（エリザベスパーク）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, 13, "花澤香菜", "AB", "「友達」に憧れる、エルフの森の女の子", 6, "エルフ", "アオイ", 0, 104001, "友達作りのイメトレ", "友達ができるその日まで…\nBB団で\nトレーニングですっ！", 158, 6, 44, "フォレスティエ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 17, "福原綾香", "O", "人々を守るために歌う、唱喚士の少女", 4, "ヒューマン", "チカ", 0, 104201, "各種楽器", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 163, 6, 46, "カルミナ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, 17, "小松未可子", "O", "男勝りで情に厚いワイルド娘", 10, "獣人族", "マコト", 0, 104301, "お菓子作り", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 168, 8, 54, "自警団（カォン）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, "??", "丹下桜", "A", "かつては夜を支配した最強の吸血鬼", 7, "魔族", "イリヤ", 0, 104401, "世界征服", "test", 172, 5, 50, "悪魔偽王国軍（ディアボロス）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (19, 18, "長妻樹里", "AB", "妄想大好き！　ほんとは照れ屋な女の子", 15, "ヒューマン", "クウカ", 0, 104501, "小説を読むこと", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 157, 11, 49, "ヴァイスフリューゲル　ランドソル支部");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, 19, "沼倉愛美", "AB", "弱きを助け強きをくじく猫娘", 12, "獣人族", "タマキ", 0, 104601, "猫とたわむれること", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 158, 3, 48, "メルクリウス財団");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (25, 25, "川澄綾子", "A", "素顔を見せない冷静沈着な女性騎士", 8, "ヒューマン", "ジュン", 0, 104701, "格闘技、湯浴み", "？？？", 171, 10, 50, "王宮騎士団（NIGHTMARE）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 20, "田所あずさ", "O", "仕事も私事も効率優先な傭兵少女", 12, "ヒューマン", "ミフユ", 0, 104801, "傭兵などのアルバイト", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 163, 11, 49, "メルクリウス財団");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (24, 18, "生天目仁美", "O", "お姉ちゃんがお世話してあげるからねっ！", 3, "ヒューマン", "シズル", 0, 104901, "家事全般", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 168, 10, 54, "ラビリンス");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 11, "久野美咲", "A", "ちょっとおませな恋に恋する女の子", 14, "魔族", "ミサキ", 0, 105001, "ファッション誌鑑賞、コスメ集め", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 120, 1, 22, "ルーセント学院");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, 27, "三石琴乃", "A", "実験が趣味の危険な科学者", 13, "ヒューマン", "ミツキ", 0, 105101, "研究、実験", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 166, 3, 53, "トワイライトキャラバン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (14, 17, "徳井青空", "A", "乙女チックなもふもふアニマル", 11, "獣人族", "リマ", 0, 105201, "毛繕い、お喋り", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", 150, 3, 100, "牧場（エリザベスパーク）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (28, 17, "辻あゆみ", "A", "見た目も中身もお子ちゃまな異国の軍人", 15, "ヒューマン", "モニカ", 0, 105301, "お菓子屋通い", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 140, 7, 33, "ヴァイスフリューゲル　ランドソル支部");
