INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (7, 16, "大関英里", "O", "どこまでも一途に慕う、純情乙女", 15, "エルフ", "アユミ", 0, 105501, "観察", "test", 155, 4, 43, "ヴァイスフリューゲル　ランドソル支部");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 25, "佐藤利奈", "B", "人情味溢れる粋でいなせな「姉御」", 13, "ヒューマン", "ルカ", 0, 105601, "釣り", "test", 167, 7, 54, "トワイライトキャラバン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 17, "金元寿子", "O", "空への冒険を夢見る騎空士の少女", "", "ヒューマン", "ジータ", 0, 105701, "冒険、おしゃべり", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", 156, 3, 45, "？？？");
