INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (31, 17, "M・A・O", "O", "いつも元気な腹ペコ少女", 1, "ヒューマン", "ペコリーヌ（サマー）", 0, 107501, "食べ歩き、料理", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 156, 3, 46, "美食殿");
