INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, 19, "沼倉愛美", "AB", "弱きを助け強きをくじく猫娘", 12, "獣人族", "タマキ（サマー）", 0, 107901, "猫とたわむれること", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 158, 3, 48, "メルクリウス財団");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (11, 20, "田所あずさ", "O", "仕事も私事も効率優先な傭兵少女", 12, "ヒューマン", "ミフユ（サマー）", 0, 108001, "傭兵などのアルバイト", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 163, 11, 49, "メルクリウス財団");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 18, "大坪由佳", "AB", "占いが得意な霊能少女", 7, "魔族", "シノブ（ハロウィン）", 0, 108101, "占い", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 157, 12, 42, "悪魔偽王国軍（ディアボロス）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (23, 14, "雨宮天", "B", "プリン大好きゴースト娘", 7, "魔族", "ミヤコ（ハロウィン）", 0, 108201, "プリンを食べること", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 130, 1, 32, "悪魔偽王国軍（ディアボロス）");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 11, "久野美咲", "A", "ちょっとおませな恋に恋する女の子", 14, "魔族", "ミサキ（ハロウィン）", 0, 108301, "ファッション誌鑑賞、コスメ集め", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 120, 1, 22, "ルーセント学院");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 17, "福原綾香", "O", "人々を守るために歌う、唱喚士の少女", 4, "ヒューマン", "チカ（クリスマス）", 0, 108401, "各種楽器", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 163, 6, 46, "カルミナ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (9, 12, "植田佳奈", "B", "泣き虫で臆病な守ってあげたい女の子", 9, "ヒューマン", "クルミ（クリスマス）", 0, 108501, "観劇、おままごと", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 150, 6, 40, "サレンディア救護院");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 14, "芹澤優", "B", "ぷうきちといつも一緒！", 9, "ヒューマン", "アヤネ（クリスマス）", 0, 108601, "屋内でできる遊び", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 148, 5, 38, "サレンディア救護院");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (27, 16, "東山奈央", "A", "人助けが大好き！　前向き格闘娘", 2, "獣人族", "ヒヨリ（ニューイヤー）", 0, 108701, "人助け、応援", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 155, 8, 44, "トゥインクルウィッシュ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 17, "種田梨沙", "O", "戦闘のサポートが得意な、心優しい少女", 2, "ヒューマン", "ユイ（ニューイヤー）", 0, 108801, "料理、人間観察", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 158, 4, 47, "トゥインクルウィッシュ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 18, "早見沙織", "B", "クールで何事にも真っ直ぐな剣士", 2, "魔族", "レイ（ニューイヤー）", 0, 108901, "読書、乗馬、お茶", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 163, 1, 46, "トゥインクルウィッシュ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (30, 16, "橋本ちなみ", "B", "運命の相手に一途すぎる乙女", 13, "魔族", "エリコ（バレンタイン）", 0, 109001, "実験、裁縫、料理", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 154, 7, 43, "トワイライトキャラバン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (24, 18, "生天目仁美", "O", "お姉ちゃんがお世話してあげるからねっ！", 3, "ヒューマン", "シズル（バレンタイン）", 0, 109101, "家事全般", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 168, 10, 54, "ラビリンス");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, 17, "日笠陽子", "AB", "英霊と契約を結んだマナリアの天才王女", "", "ヒューマン", "アン", 0, 109201, "読書", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", 156, 12, 55, "？？？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (4, 16, "こやまきみこ", "O", "マナリア魔法学院の新入生", "", "ヒューマン", "ルゥ", 0, 109301, "食べること、眠ること", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", 144, 2, 45, "？？？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (3, 17, "福原綾香", "B", "人を超越した力を有す心優しい竜姫", "", "半人半竜", "グレア", 0, 109401, "ピアノ", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", 167, 11, 67, "？？？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (19, 18, "長妻樹里", "AB", "妄想大好き！　ほんとは照れ屋な女の子", 15, "ヒューマン", "クウカ（オーエド）", 0, 109501, "小説を読むこと", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 157, 11, 49, "ヴァイスフリューゲル　ランドソル支部");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (31, 16, "佐藤聡美", "O", "トーゴクの神秘、オシエテクダサイ！", 15, "ヒューマン", "ニノン（オーエド）", 0, 109601, "忍法開発", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 163, 8, 51, "ヴァイスフリューゲル　ランドソル支部");
