INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 16, "内田真礼", "O", "マホマホ王国のプリンセス", 10, "獣人族", "マホ（シンデレラ）", 0, 116001, "空想、ぬいぐるみ集め", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 155, 9, 42, "自警団（カォン）");
