INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (1, 19, "沼倉愛美", "AB", "弱きを助け強きをくじく猫娘", 12, "獣人族", "タマキ（作業服）", 0, 116801, "猫とたわむれること", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 158, 3, 48, "メルクリウス財団");
