INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (10, 14, "大空直美", "AB", "ボクは誰よりも美しい", 15, "エルフ", "ユキ（オーエド）", 0, 117601, "鏡で自分を見ること", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 150, 10, 40, "ヴァイスフリューゲル　ランドソル支部");
