INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (5, 17, "髙野麻美", "A", "前世を信じる中二病患者、「疾風の冥姫」", 13, "魔族", "アンナ（パイレーツ）", 0, 121901, "小説執筆", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 159, 7, 45, "トワイライトキャラバン");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (22, 18, "大坪由佳", "AB", "占いが得意な霊能少女", 7, "魔族", "シノブ（パイレーツ）", 0, 122001, "占い", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 157, 12, 42, "悪魔偽王国軍（ディアボロス）");
