INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (6, "??", "釘宮理恵", "AB", "けんぞくのご主人様", "", "魔族", "ヴァンピィ", 0, 122301, "お散歩、お料理", "", 149, 12, 41, "？？？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (27, 16, "東山奈央", "A", "人助けが大好き！　前向き格闘娘", 2, "獣人族", "ヒヨリ（サマー）", 0, 122401, "人助け、応援", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 155, 8, 44, "トゥインクルウィッシュ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (12, 18, "早見沙織", "B", "クールで何事にも真っ直ぐな剣士", 2, "魔族", "レイ（サマー）", 0, 122501, "読書、乗馬、お茶", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 163, 1, 46, "トゥインクルウィッシュ");
